    std::size_t parts{0};
    int         open_edges{0};
    int         edges_fixed{0}, degenerate_facets{0}, facets_removed{0}, facets_reversed{0}, backwards_edges{0};
    std::string units_suspicion; // empty, "inches", or "meters": Orca's own load-time tests
};

